/* FitCampus stays intentionally framework-free so the demo can be opened from VS Code.
   The repository boundary is kept behind Store, making a future API adapter straightforward. */
const KEYS={users:"fc_users",session:"fc_session",activities:"fc_activities",favorites:"fc_favorites",water:"fc_water",plans:"fc_plans",challenges:"fc_challenges",events:"fc_events",badges:"fc_custom_badges"};
const ADMIN_PASSWORD="shashank";
let adminUnlocked=sessionStorage.getItem("fc_admin_unlocked")==="1";
const uid=()=>crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const today=()=>new Date().toISOString().slice(0,10);
const dateLabel=d=>new Intl.DateTimeFormat("en-IN",{day:"numeric",month:"short"}).format(new Date(`${d}T12:00:00`));
const escapeHtml=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const Store={get(key,fallback=[]){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}},set(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast("Storage is unavailable. Your change could not be saved.");return false}},users(){return this.get(KEYS.users)},user(){const id=localStorage.getItem(KEYS.session);return this.users().find(u=>u.id===id)},saveUser(u){const all=this.users();const i=all.findIndex(x=>x.id===u.id);i<0?all.push(u):all[i]=u;this.set(KEYS.users,all)},activities(){return this.get(KEYS.activities)},userActivities(){const u=this.user();return this.activities().filter(a=>a.userId===u?.id)},favorites(){return this.get(KEYS.favorites)},isFavorite(id){const u=this.user();return !!u&&this.favorites().some(f=>f.userId===u.id&&f.itemId===id)},toggleFavorite(id){const u=this.user();if(!u)return;let all=this.favorites();const i=all.findIndex(f=>f.userId===u.id&&f.itemId===id);i>=0?all.splice(i,1):all.push({userId:u.id,itemId:id});this.set(KEYS.favorites,all)},water(){return this.get(KEYS.water,{})}};
