let state={route:"home",exerciseFilter:"All",timer:null};
function toast(message){const el=document.createElement("div");el.className="toast";el.textContent=message;document.getElementById("toast-region").append(el);setTimeout(()=>el.remove(),3200)}
function bmi(user){if(!user.height||!user.weight)return null;return +(user.weight/((user.height/100)**2)).toFixed(1)}
function bmiInfo(value,age){if(!value)return{category:"Add height & weight",tone:""};if(age<18)return{category:"Age-appropriate guidance",tone:""};if(value<18.5)return{category:"Underweight",tone:"low"};if(value<25)return{category:"Healthy range",tone:"good"};if(value<30)return{category:"Overweight",tone:"mid"};return{category:"Obesity range",tone:"high"}}
function bmiPlan(value,age){if(!value)return{title:"Complete your BMI profile",summary:"Add your age, height and weight to receive a plan tailored to your current needs.",items:["5-minute mobility","3-minute desk movement","10-minute comfortable walk"],note:"BMI is a screening measure, not a diagnosis."};if(age<18)return{title:"Age-appropriate movement plan",summary:"Adult BMI categories are not medically appropriate under 18. Focus on enjoyable movement, regular meals and guidance from a qualified professional.",items:["10-minute playful cardio","5-minute mobility","5-minute breathing"],note:"For under-18 users, use age-appropriate clinical guidance."};if(value<18.5)return{title:"Build strength and steady energy",summary:"Prioritise regular meals, adequate protein and progressive strength work. Avoid extreme bulking or supplements.",items:["5-minute mobility","20-minute full-body strength","5-minute gentle stretch"],note:"General wellness guidance only; consult a professional for personalised nutrition advice."};if(value<25)return{title:"Maintain your healthy rhythm",summary:"Keep a balanced routine with strength, cardio, mobility, sleep and regular meals. Consistency matters more than intensity.",items:["5-minute morning mobility","3-minute study break","20-minute mixed workout"],note:"Your BMI is in the standard adult healthy range, but BMI is only a screening measure."};if(value<30)return{title:"Build gradual, sustainable habits",summary:"Use comfortable moderate activity, balanced portions and regular movement. Avoid crash diets and excessive exercise.",items:["5-minute mobility","10-minute low-impact cardio","10-minute strength circuit"],note:"Consider professional guidance if you have health conditions or concerns."};return{title:"Supportive gradual lifestyle plan",summary:"Start with low-impact movement and sustainable food habits. Do not use starvation, purging, unsafe supplements or extreme exercise.",items:["5-minute mobility","10-minute easy walk","5-minute breathing or stretch"],note:"Professional guidance is recommended for personalised care."}}
function calorieEstimate(user){const weight=Number(user.weight),height=Number(user.height),age=Number(user.age);if(!weight||!height||!age)return null;const sex=user.gender==="Male"?5:user.gender==="Female"?-161:-78;const bmr=10*weight+6.25*height-5*age+sex;const factor={Sedentary:1.2,Light:1.375,Moderate:1.55,Active:1.725}[user.activityLevel||"Light"]||1.375;return Math.round(bmr*factor)}
function calorieModal(){const u=Store.user(),estimate=calorieEstimate(u);openModal("Calorie estimate",`<div class="card" style="background:var(--mint);box-shadow:none;margin-bottom:18px"><p class="eyebrow">GENERAL WELLNESS ESTIMATE</p><p class="metric">${estimate||"—"} <small style="font-size:.9rem">kcal/day</small></p><p class="muted" style="margin-top:8px;line-height:1.5">${estimate?"This is an approximate maintenance estimate based on your stored profile. It is not a medical prescription.":"Complete age, gender, height and weight in your profile first."}</p></div><p class="modal-copy">Calorie needs vary with health, sleep, goals and daily activity. Do not use this estimate for extreme restriction. Students with medical conditions, eating disorders, pregnancy or special dietary needs should consult a qualified professional.</p><div class="timer-controls"><button class="btn btn-primary" data-route-modal="profile">Update profile</button><button class="btn btn-ghost" data-close-modal>Close</button></div>`)}
function tutorialMarkup(url){try{const parsed=new URL(url);if(!["http:","https:"].includes(parsed.protocol))throw new Error("Unsupported tutorial URL");const host=parsed.hostname.toLowerCase();let embed="";if(host.includes("youtube.com")||host.includes("youtu.be")){const id=host.includes("youtu.be")?parsed.pathname.slice(1):parsed.searchParams.get("v");if(id)embed=`<iframe class="tutorial-frame" src="https://www.youtube.com/embed/${encodeURIComponent(id)}" title="Exercise tutorial" loading="lazy" allowfullscreen></iframe>`}else if(host.includes("vimeo.com")){const id=parsed.pathname.split("/").filter(Boolean).pop();if(id)embed=`<iframe class="tutorial-frame" src="https://player.vimeo.com/video/${encodeURIComponent(id)}" title="Exercise tutorial" loading="lazy" allowfullscreen></iframe>`}else if(/\.(mp4|webm|ogg)(\?.*)?$/i.test(parsed.pathname)){embed=`<video class="tutorial-frame" controls preload="metadata" src="${escapeHtml(parsed.href)}"></video>`}return`<div class="tutorial-link"><p class="kicker">Tutorial video</p>${embed||`<p class="muted">This link cannot be embedded by the provider.</p>`}<a class="btn btn-secondary" href="${escapeHtml(parsed.href)}" target="_blank" rel="noopener noreferrer">Open source link ↗</a><small class="muted">${escapeHtml(parsed.hostname)}</small></div>`}catch{return`<div class="tutorial-link"><p class="kicker">Tutorial</p><span class="muted">No tutorial link added yet.</span></div>`}}
function bmiCalculatorModal(){const u=Store.user();openModal("Calculate your BMI",`<form id="bmi-form" class="form-stack"><div class="form-grid"><label class="field">Age (years)<input name="age" type="number" min="1" max="120" value="${u.age||""}" required></label><label class="field">Gender<select name="gender"><option>${u.gender||"Prefer not to say"}</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Prefer not to say</option></select></label><label class="field">Height (cm)<input name="height" type="number" min="80" max="250" value="${u.height||""}" required></label><label class="field">Weight (kg)<input name="weight" type="number" min="20" max="300" value="${u.weight||""}" required></label></div><p id="bmi-form-error" class="form-error" role="alert"></p><button class="btn btn-primary" type="submit">Calculate and personalise plan</button></form>`)}
function userStats(){const u=Store.user(),acts=Store.userActivities(),dates=[...new Set(acts.map(a=>a.date))].sort();let streak=0, cursor=new Date();for(let i=0;i<365;i++){const d=cursor.toISOString().slice(0,10);if(dates.includes(d)){streak++;cursor.setDate(cursor.getDate()-1)}else break}let longest=0,run=0,prev=null;dates.forEach(d=>{if(prev&&((new Date(`${d}T12:00:00`)-new Date(`${prev}T12:00:00`))/86400000===1))run++;else run=1;longest=Math.max(longest,run);prev=d});return{u,acts,streak,longest,weekMins:acts.filter(a=>(Date.now()-new Date(`${a.date}T12:00:00`))/86400000<7).reduce((n,a)=>n+a.duration,0),weekSessions:acts.filter(a=>(Date.now()-new Date(`${a.date}T12:00:00`))/86400000<7).length}}
function awardActivity(exercise,minutes=exercise.duration,category=exercise.category){const u=Store.user();if(!u)return;const now=today();const exists=Store.userActivities().some(a=>a.date===now&&a.exerciseId===exercise.id&&a.sessionKey===state.timer?.sessionKey);if(exists)return;const points=minutes>=20?20:minutes>=10?10:5;const activity={id:uid(),userId:u.id,date:now,exerciseId:exercise.id,exerciseName:exercise.name,category,duration:minutes,points,caloriesEstimate:Math.round(minutes*4.5),sessionKey:state.timer?.sessionKey};const all=Store.activities();all.push(activity);Store.set(KEYS.activities,all);const updated={...u,points:(u.points||0)+points};Store.saveUser(updated);toast(`+${points} points · activity saved`);render()}
function openModal(title,body){document.getElementById("modal-root").innerHTML=`<div class="modal-backdrop" data-close-modal><section class="modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="modal-head"><div><p class="eyebrow">FITCAMPUS</p><h2>${escapeHtml(title)}</h2></div><button class="close-btn" data-close-modal aria-label="Close">×</button></div>${body}</section></div>`;bindModalControls()}
function closeModal(){if(state.timer?.interval){clearInterval(state.timer.interval);state.timer.interval=null}document.getElementById("modal-root").innerHTML=""}
function bindModalControls(){const root=document.getElementById("modal-root"),start=root.querySelector("[data-start-ex]");const modalRoute=root.querySelector("[data-route-modal]");if(modalRoute)modalRoute.onclick=()=>{closeModal();state.route=modalRoute.dataset.routeModal;render()};if(start)start.onclick=()=>{const ex=exercises.find(x=>x.id===start.dataset.startEx);if(ex)startTimer(ex)};const bmiForm=root.querySelector("#bmi-form");if(bmiForm)bmiForm.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(bmiForm)),age=Number(data.age),height=Number(data.height),weight=Number(data.weight);const error=root.querySelector("#bmi-form-error");if(!age||age<1||!height||height<80||!weight||weight<20){error.textContent="Please enter a valid age, height and weight.";return}const u=Store.user(),updated={...u,...data,age,height,weight,bmi:bmi({height,weight})};Store.saveUser(updated);closeModal();toast("BMI calculated and plan personalised");render()};const close=root.querySelector(".close-btn");if(close)close.onclick=closeModal;const backdrop=root.querySelector(".modal-backdrop");if(backdrop)backdrop.onclick=e=>{if(e.target===backdrop)closeModal()};const play=root.querySelector("[data-motion-play]");if(play)play.onclick=()=>{const stage=root.querySelector("[data-motion-stage]");stage?.classList.toggle("playing");play.textContent=stage?.classList.contains("playing")?"Pause":"Play"};const slow=root.querySelector("[data-motion-slow]");if(slow)slow.onclick=()=>root.querySelector("[data-motion-stage]")?.classList.toggle("slow");const rotate=root.querySelector("[data-motion-rotate]");if(rotate)rotate.onclick=()=>{const stage=root.querySelector("[data-motion-stage]");if(stage)stage.style.transform=`rotateY(${Math.round(Math.random()*160-80)}deg) rotateX(${Math.round(Math.random()*20-10)}deg)`};const toggle=root.querySelector("[data-timer-toggle]");if(toggle)toggle.onclick=()=>{state.timer.running=!state.timer.running;toggle.textContent=state.timer.running?"Pause":"Resume"};const reset=root.querySelector("[data-timer-reset]");if(reset)reset.onclick=()=>{state.timer.remaining=state.timer.total;const live=root.querySelector("#live-timer");if(live)live.textContent=formatTime(state.timer.remaining)};const finish=root.querySelector("[data-timer-finish]");if(finish)finish.onclick=()=>{const ex=state.timer.exercise,mins=Math.max(1,Math.ceil((state.timer.total-state.timer.remaining)/60));awardActivity(ex,mins,ex.category);closeModal()}}
function exerciseModal(ex){const fav=Store.isFavorite(ex.id),benefits=ex.benefits||"Supports consistency, mobility and everyday energy.";openModal(ex.name,`<div class="motion-viewer"><div class="motion-stage" data-motion-stage>${ex.icon}</div><div class="motion-caption" data-motion-caption>3D-style movement preview · ready</div><div class="motion-controls"><button class="btn btn-secondary" data-motion-play>Play</button><button class="btn btn-ghost" data-motion-slow>Slow motion</button><button class="btn btn-ghost" data-motion-rotate>Rotate</button></div></div><p class="modal-copy">${escapeHtml(ex.description)}</p><div class="grid grid-3"><div><p class="kicker">Benefits</p><p class="modal-copy">${escapeHtml(benefits)}</p></div><div><p class="kicker">How to do it</p><p class="modal-copy">${escapeHtml(ex.instructions)}</p></div><div><p class="kicker">Safety tip</p><p class="modal-copy">${escapeHtml(ex.safetyTips)}</p></div></div><div class="pill" style="background:var(--mint);color:var(--green-dark);display:inline-block;margin-bottom:18px">${ex.category} · ${ex.difficulty} · ${ex.duration} min</div>${tutorialMarkup(ex.tutorialUrl)}<div class="timer-controls"><button class="btn btn-primary" data-start-ex="${ex.id}">Start workout</button><button class="btn btn-ghost" data-favorite="${ex.id}">${fav?"★ Saved":"☆ Add to favorites"}</button></div>`)}
function render(){const user=Store.user();if(!user){document.getElementById("auth-view").classList.remove("hidden");document.getElementById("app-view").classList.add("hidden");return}document.getElementById("auth-view").classList.add("hidden");document.getElementById("app-view").classList.remove("hidden");document.getElementById("top-name").textContent=user.name;document.getElementById("top-department").textContent=user.department||"Student";document.getElementById("top-avatar").textContent=user.name.charAt(0).toUpperCase();document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.route===state.route));document.getElementById("page-title").textContent=state.route==="home"?"Home":state.route.charAt(0).toUpperCase()+state.route.slice(1);document.getElementById("sidebar-message").textContent=motivation();const content=document.getElementById("page-content");content.innerHTML=pages[state.route]?pages[state.route]():pages.home();if(state.route==="dashboard"){const b=bmi(user),p=bmiPlan(b,user.age);content.insertAdjacentHTML("beforeend",`<section class="card" style="margin-top:18px"><div class="section-title" style="margin:0 0 10px"><h3>${p.title}</h3><button class="btn btn-secondary" data-open-bmi>Update BMI</button></div><p class="muted" style="line-height:1.6">${p.summary}</p><div class="grid grid-3" style="margin-top:15px">${p.items.map((item,i)=>`<div class="plan-row"><span class="plan-time">${["Step 1","Step 2","Step 3"][i]}</span><div><strong>${item}</strong><small>Comfortable, sustainable progress</small></div></div>`).join("")}</div><p class="muted" style="font-size:.75rem;margin-top:13px">${p.note}</p></section>`)}bindPage()}
function motivation(){const s=userStats();if(!s.acts.length)return"Your first small win is waiting.";if(s.streak>=3)return`🔥 You're on a ${s.streak}-day streak!`;if(s.weekSessions>=3)return"💪 Your consistency is showing this week.";return"📚 Long study session? Your body needs a break too."}
const pages={
home(){const u=Store.user();return`<div class="page-heading"><div><p class="eyebrow">YOUR WELLNESS HQ</p><h2>Make space for your best self.</h2><p class="muted">A little movement goes a long way between lectures.</p></div><button class="btn btn-primary" data-route="dashboard">Open dashboard →</button></div><section class="card feature-hero"><div><p class="eyebrow">THE FITCAMPUS METHOD</p><h2>Small habits.<br><span style="color:var(--green)">Real momentum.</span></h2><p>Built for students who have ten minutes, a desk and a lot on their plate. Move in a way that fits your day.</p></div><div style="font-size:6rem">✦</div></section><div class="section-title"><h3>Explore your campus toolkit</h3></div><div class="grid grid-3"><button class="card quick-action" data-route="desk"><span>⌁</span>Desk Fitness<small class="muted">Reset between study blocks</small></button><button class="card quick-action" data-route="yoga"><span>◌</span>Yoga Studio<small class="muted">Breathe, stretch, restore</small></button><button class="card quick-action" data-route="nutrition"><span>◒</span>Nutrition Center<small class="muted">Affordable, practical meals</small></button></div><div class="section-title"><h3>Why students choose FitCampus</h3></div><div class="grid grid-3"><div class="card"><span class="eyebrow">01 / FLEXIBLE</span><h3>Fits around lectures</h3><p class="muted" style="margin-top:9px;line-height:1.6">Five-minute desk resets and equipment-free plans work in real campus spaces.</p></div><div class="card"><span class="eyebrow">02 / PERSONAL</span><h3>Progress that is yours</h3><p class="muted" style="margin-top:9px;line-height:1.6">Your activity, points and streaks are calculated from what you actually complete.</p></div><div class="card"><span class="eyebrow">03 / KIND</span><h3>Wellness, not punishment</h3><p class="muted" style="margin-top:9px;line-height:1.6">No crash diets or unrealistic targets. Just supportive guidance and better habits.</p></div></div>`},
dashboard(){const s=userStats(),u=s.u,b=bmi(u),bi=bmiInfo(b,u.age),goal=u.weeklyGoal||60,pct=Math.min(100,Math.round(s.weekMins/goal*100));const bp=bmiPlan(b,u.age);const plans=[["Morning",bp.items[0],"Start gently"],["Study break",bp.items[1],"Reset your focus"],["Evening",bp.items[2],"Build your rhythm"],["Night","5 min breathing","Close the day"]];return`<div class="page-heading"><div><p class="eyebrow">GOOD ${new Date().getHours()<12?"MORNING":new Date().getHours()<18?"AFTERNOON":"EVENING"}, ${escapeHtml(u.name.split(" ")[0]).toUpperCase()}</p><h2>Your day, your rhythm.</h2><p class="muted">Here’s your real-time wellness snapshot.</p></div><button class="btn btn-secondary" data-route="plans">Personalise plan</button></div><div class="card welcome-card"><div class="welcome-copy"><p class="eyebrow">KEEP GOING</p><h2>${s.streak?`You're building a ${s.streak}-day rhythm.`:"Your first win starts today."}</h2><p>${s.acts.length?`${s.weekSessions} session${s.weekSessions===1?"":"s"} logged this week. Keep showing up for yourself.`:"Complete a short session and your dashboard will start learning your rhythm."}</p><div class="welcome-pills"><span class="pill"><strong>🔥 ${s.streak}</strong> current streak</span><span class="pill"><strong>✦ ${u.points||0}</strong> points</span><span class="pill"><strong>◷ ${s.acts.length}</strong> total workouts</span></div></div></div><div class="section-title"><h3>Your snapshot</h3><button class="link-btn" data-route="progress">View analytics →</button></div><div class="grid grid-4"><div class="card metric-card"><span class="icon">◷</span><span class="kicker">This week</span><p class="metric">${s.weekMins}<small style="font-size:.85rem"> min</small></p><small class="muted">${s.weekSessions} sessions</small></div><div class="card metric-card"><span class="icon">♨</span><span class="kicker">BMI</span><p class="metric">${b||"—"}</p><small class="muted">${bi.category}</small></div><div class="card metric-card"><span class="icon">✦</span><span class="kicker">All-time points</span><p class="metric">${u.points||0}</p><small class="muted">Earned by you</small></div><div class="card metric-card"><span class="icon">⌁</span><span class="kicker">Longest streak</span><p class="metric">${s.longest}<small style="font-size:.85rem"> days</small></p><small class="muted">Your best run</small></div></div><div class="grid grid-2" style="margin-top:18px"><section class="card"><div class="section-title" style="margin:0 0 20px"><h3>Weekly goal</h3><span class="kicker">${s.weekMins}/${goal} min</span></div><div class="ring-layout"><div class="progress-ring" style="--value:${pct}"><strong>${pct}%</strong></div><div><h3>${pct>=100?"Goal complete!":"Keep your momentum."}</h3><p class="muted" style="margin-top:8px;line-height:1.5">${pct>=100?"You earned your weekly goal bonus by moving consistently.":"A few focused minutes today can move this ring."}</p></div></div></section><section class="card"><div class="section-title" style="margin:0 0 13px"><h3>Today's plan</h3><button class="link-btn" data-route="plans">Edit</button></div><div class="plan-list">${plans.map(p=>`<div class="plan-row"><span class="plan-time">${p[0]}</span><div><strong>${p[1]}</strong><small>${p[2]}</small></div></div>`).join("")}</div></section></div><div class="section-title"><h3>Quick actions</h3></div><div class="quick-actions"><button class="quick-action" data-route="exercises"><span>▶</span>Start workout</button><button class="quick-action" data-route="desk"><span>⌁</span>Desk break</button><button class="quick-action" data-route="yoga"><span>◌</span>Yoga</button><button class="quick-action" data-route="nutrition"><span>◒</span>Nutrition</button><button class="quick-action" data-open-bmi><span>♨</span>Calculate BMI</button><button class="quick-action" data-calorie-estimate><span>◔</span>Calorie estimate</button><button class="quick-action" data-log-activity><span>＋</span>Log activity</button></div>`},
exercises(){const cats=["All",...new Set(exercises.map(e=>e.category))];const filtered=exercises.filter(e=>(state.exerciseFilter==="All"||e.category===state.exerciseFilter)&&(state.search?e.name.toLowerCase().includes(state.search):true));return`<div class="page-heading"><div><p class="eyebrow">MOVE YOUR WAY</p><h2>Exercise library</h2><p class="muted">Short, clear sessions for your body and your schedule.</p></div><button class="btn btn-primary" data-route="plans">Build a plan</button></div><div class="filter-row"><div class="search-box"><span>⌕</span><input id="exercise-search" value="${escapeHtml(state.search||"")}" placeholder="Search exercises..." aria-label="Search exercises"></div><select id="category-filter" aria-label="Filter by category">${cats.map(c=>`<option ${state.exerciseFilter===c?"selected":""}>${c}</option>`).join("")}</select></div><div class="grid grid-3">${filtered.map(ex=>`<article class="card exercise-card"><div class="exercise-art">${ex.icon}</div><div class="exercise-body"><div class="exercise-meta"><span class="tag">${ex.category}</span><span class="difficulty">${ex.difficulty}</span></div><h3>${ex.name}</h3><p>${ex.description}</p><div class="exercise-footer"><small>${ex.duration} min · ${ex.muscles.split(" · ")[0]}</small><button class="text-btn" data-exercise="${ex.id}">View details →</button></div></div></article>`).join("")||`<div class="card empty-state" style="grid-column:1/-1"><span class="empty-icon">⌕</span><h3>No exercises found</h3><p>Try a different search or category.</p></div>`}</div>`},
desk(){const desk=exercises.filter(e=>e.category==="Desk");return`<div class="page-heading"><div><p class="eyebrow">STUDY SMARTER</p><h2>Desk Fitness</h2><p class="muted">Release tension without leaving your study spot.</p></div><button class="btn btn-primary" data-desk-start>Start 5-minute break</button></div><section class="card feature-hero"><div><p class="eyebrow">YOUR RESET BUTTON</p><h2>5-minute study break</h2><p>Shoulders, neck, wrists, back and legs — a guided reset for long library days.</p></div><div class="timer-display" style="font-size:3rem">05:00</div></section><div class="section-title"><h3>Desk-friendly movements</h3><span class="kicker">${desk.length} exercises</span></div><div class="grid grid-3">${desk.map(ex=>`<article class="card exercise-card"><div class="exercise-art">${ex.icon}</div><div class="exercise-body"><div class="exercise-meta"><span class="tag">${ex.category}</span><span class="difficulty">${ex.duration} min</span></div><h3>${ex.name}</h3><p>${ex.description}</p><button class="btn btn-secondary" style="width:100%" data-exercise="${ex.id}">Learn movement</button></div></article>`).join("")}</div>`},
yoga(){return`<div class="page-heading"><div><p class="eyebrow">BREATHE & RESET</p><h2>Yoga studio</h2><p class="muted">Guided sessions for energy, mobility and calmer study days.</p></div></div><div class="tabs">${["All","Morning Yoga","Study Break","Stress Relief"].map(c=>`<button class="tab ${c==="All"?"active":""}">${c}</button>`).join("")}</div><div class="grid grid-3">${yogaSessions.map(s=>`<article class="card"><div class="exercise-art" style="height:120px">${s.id==="yoga-5"?"◒":s.id==="yoga-10"?"☀":"◌"}</div><p class="eyebrow" style="margin-top:17px">${s.category}</p><h3>${s.name}</h3><p class="muted" style="margin:8px 0 17px">${s.duration} min · ${s.poses.length} poses · Beginner friendly</p><button class="btn btn-primary" style="width:100%" data-yoga-start="${s.id}">Start session</button></article>`).join("")}</div><div class="section-title"><h3>Learn the poses</h3></div><div class="grid grid-4">${exercises.filter(e=>e.category==="Yoga").map(e=>`<article class="card exercise-card"><div class="exercise-art" style="height:100px">${e.icon}</div><div class="exercise-body"><h3>${e.name}</h3><p>${e.description}</p><button class="text-btn" data-exercise="${e.id}">View pose →</button></div></article>`).join("")}</div>`},
plans(){const u=Store.user();return`<div class="page-heading"><div><p class="eyebrow">YOUR RHYTHM, DESIGNED</p><h2>Workout plans</h2><p class="muted">A simple plan built from your goal and available time.</p></div><button class="btn btn-primary" data-generate-plan>Generate plan</button></div><section class="card"><div class="form-grid"><div class="field"><label>Fitness goal<select id="goal-select"><option>${u.fitnessGoal||"General fitness"}</option><option>Weight management</option><option>Muscle building</option><option>Flexibility</option><option>Stress reduction</option><option>Endurance</option></select></label></div><div class="field"><label>Available time<select id="time-select"><option>${u.availableTime||"20"} minutes</option><option>5 minutes</option><option>10 minutes</option><option>20 minutes</option><option>30 minutes</option><option>45+ minutes</option></select></label></div><div class="field"><label>Experience<select id="experience-select"><option>${u.experience||"Beginner"}</option><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label></div><div class="field"><label>Equipment<select id="equipment-select"><option>${u.equipment||"No equipment"}</option><option>No equipment</option><option>Chair</option><option>Resistance band</option><option>Dumbbells</option><option>Full gym</option></select></label></div></div></section><div id="generated-plan" style="margin-top:18px">${planMarkup(u)}</div>`},
nutrition(){const u=Store.user(),b=bmi(u),bi=bmiInfo(b,u.age),diet=u.dietaryPreference||"Vegetarian";return`<div class="page-heading"><div><p class="eyebrow">FUEL YOUR CAMPUS LIFE</p><h2>Nutrition center</h2><p class="muted">Affordable ideas for steady energy — never a medical prescription.</p></div><button class="btn btn-secondary" data-save-plan>Save weekly plan</button></div><div class="notice">General wellness guidance only. If you have a medical condition, an eating disorder, are pregnant or have special dietary needs, please consult a qualified dietitian or healthcare professional.</div><div class="grid grid-2" style="margin-top:18px"><section class="card"><p class="eyebrow">YOUR DIRECTION</p><h3>${bi.category==="Underweight"?"Adequate energy & protein":bi.category==="Overweight"||bi.category==="Obesity range"?"Balanced portions & regular activity":"Balanced nutrition & maintenance"}</h3><p class="muted" style="line-height:1.6;margin-top:9px">Based on your profile (${diet}, ${u.budget||"₹100/day"} budget). Focus on affordable, nutrient-dense staples — not extreme restriction.</p><div class="form-grid" style="margin-top:20px"><div class="field"><label>Dietary preference<select id="diet-select"><option ${diet==="Vegetarian"?"selected":""}>Vegetarian</option><option ${diet==="Eggitarian"?"selected":""}>Eggitarian</option><option ${diet==="Non-vegetarian"?"selected":""}>Non-vegetarian</option></select></label></div><div class="field"><label>Daily budget<select id="budget-select"><option>${u.budget||"₹100/day"}</option><option>₹50/day</option><option>₹75/day</option><option>₹100/day</option><option>₹150/day</option><option>₹200+/day</option></select></label></div></div></section><section class="card"><div class="section-title" style="margin:0 0 10px"><h3>Water tracker</h3><span class="kicker">${Store.water()[`${u.id}-${today()}`]||0}/8 glasses</span></div><p class="muted">A gentle reminder, not an exact universal requirement.</p><div class="bar-track" style="margin:19px 0"><i style="width:${Math.min(100,(Store.water()[`${u.id}-${today()}`]||0)/8*100)}%"></i></div><div class="timer-controls"><button class="btn btn-secondary" data-water="-1">−</button><button class="btn btn-primary" data-water="1">Log a glass +</button></div></section></div><div class="section-title"><h3>Affordable weekly meal planner</h3><button class="link-btn" data-regenerate>↻ Regenerate</button></div><section class="card table-wrap"><table class="table"><thead><tr><th>Meal</th><th>Food</th><th>Approx. cost</th><th>Protein source</th><th>Prep</th></tr></thead><tbody>${[...Array(7)].flatMap((_,d)=>meals.map((m,i)=>`<tr><td><b>${i===0?["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"][d]:""}</b><br><small class="muted">${m[1]}</small></td><td>${m[0]}</td><td>${m[2]}</td><td>${m[3]}</td><td>${m[4]} min</td></tr>`)).join("")}</tbody></table><p class="muted" style="margin-top:16px;font-size:.78rem">Approximate plan total: ₹${meals.reduce((n,m)=>n+parseInt(m[2].replace("₹","")),0)*7}/week · portions are flexible and should suit your appetite.</p></section>`},
progress(){const s=userStats(),byDay=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=d.toISOString().slice(0,10);return{label:["S","M","T","W","T","F","S"][d.getDay()],value:s.acts.filter(a=>a.date===key).reduce((n,a)=>n+a.duration,0)}}),cats={};s.acts.forEach(a=>cats[a.category]=(cats[a.category]||0)+a.duration);const max=Math.max(1,...byDay.map(x=>x.value));return`<div class="page-heading"><div><p class="eyebrow">YOUR DATA, YOUR STORY</p><h2>Progress</h2><p class="muted">Every chart is built from sessions you actually completed.</p></div></div>${!s.acts.length?`<section class="card empty-state"><span class="empty-icon">↗</span><h3>No activity yet.</h3><p>Complete your first workout to start your progress journey.</p><button class="btn btn-primary" style="margin-top:18px" data-route="exercises">Find a session</button></section>`:`<><div class="grid grid-4"><div class="card metric-card"><span class="kicker">Total minutes</span><p class="metric">${s.acts.reduce((n,a)=>n+a.duration,0)}</p></div><div class="card metric-card"><span class="kicker">Sessions</span><p class="metric">${s.acts.length}</p></div><div class="card metric-card"><span class="kicker">Points earned</span><p class="metric">${s.u.points||0}</p></div><div class="card metric-card"><span class="kicker">Current streak</span><p class="metric">${s.streak} <small style="font-size:.8rem">days</small></p></div></div><div class="grid grid-2" style="margin-top:18px"><section class="card"><div class="section-title" style="margin:0"><h3>Workout minutes · last 7 days</h3></div><div class="chart-area">${byDay.map(x=>`<div class="chart-col"><i style="height:${x.value/max*100}%"></i><span>${x.value}m</span><b>${x.label}</b></div>`).join("")}</div></section><section class="card"><div class="section-title" style="margin:0"><h3>Category mix</h3></div><div class="bar-list">${Object.entries(cats).map(([k,v])=>`<div class="bar-line"><span>${k}</span><div class="bar-track"><i style="width:${v/Math.max(...Object.values(cats))*100}%"></i></div><b>${v}m</b></div>`).join("")}</div></section></div></>`}<div class="section-title"><h3>Badges</h3></div><div class="card badge-grid">${badgeMarkup(s).join("")}</div>`},
leaderboard(){const users=Store.users().map(u=>({...u,total:Store.activities().filter(a=>a.userId===u.id).reduce((n,a)=>n+a.points,0)})).sort((a,b)=>b.total-a.total);return`<div class="page-heading"><div><p class="eyebrow">CAMPUS, TOGETHER</p><h2>Leaderboard</h2><p class="muted">Only registered students and earned points appear here.</p></div></div><div class="tabs"><button class="tab active">All time</button><button class="tab">This week</button><button class="tab">This month</button><button class="tab">Department</button></div><section class="card table-wrap">${users.length?`<table class="table"><thead><tr><th>Rank</th><th>Student</th><th>Department</th><th>Points</th><th>Streak</th></tr></thead><tbody>${users.map((u,i)=>`<tr class="${u.id===Store.user().id?"current-row":""}"><td><span class="rank">#${i+1}</span></td><td><b>${escapeHtml(u.name)} ${u.id===Store.user().id?"(you)":""}</b></td><td>${escapeHtml(u.department||"—")}</td><td><b>${u.total}</b></td><td>🔥 ${u.streak||0}</td></tr>`).join("")}</tbody></table>`:`<div class="empty-state"><span class="empty-icon">♜</span><h3>Invite your classmates to start the competition.</h3></div>`}</section>`},
profile(){const u=Store.user(),b=bmi(u),bi=bmiInfo(b,u.age),s=userStats();return`<div class="page-heading"><div><p class="eyebrow">YOUR PROFILE</p><h2>Build a profile that fits you.</h2><p class="muted">Keep your details current for better recommendations.</p></div><div class="pill" style="background:var(--mint);color:var(--green-dark)">✦ ${u.points||0} points</div></div><div class="grid grid-2"><section class="card"><div class="section-title" style="margin:0 0 20px"><h3>Personal details</h3><span class="avatar">${u.name.charAt(0)}</span></div><form id="profile-form" class="form-grid"><div class="field"><label>Name<input name="name" value="${escapeHtml(u.name)}" required></label></div><div class="field"><label>Department<input name="department" value="${escapeHtml(u.department||"")}" required></label></div><div class="field"><label>Age<input name="age" type="number" min="10" max="100" value="${u.age||""}"></label></div><div class="field"><label>Gender<select name="gender"><option>${u.gender||"Prefer not to say"}</option><option>Female</option><option>Male</option><option>Non-binary</option><option>Prefer not to say</option></select></label></div><div class="field"><label>Height (cm)<input name="height" type="number" min="80" max="250" value="${u.height||""}"></label></div><div class="field"><label>Weight (kg)<input name="weight" type="number" min="20" max="300" value="${u.weight||""}"></label></div><div class="field"><label>Fitness goal<select name="fitnessGoal"><option>${u.fitnessGoal||"General fitness"}</option><option>Weight management</option><option>Muscle building</option><option>Flexibility</option><option>Stress reduction</option><option>Endurance</option></select></label></div><div class="field"><label>Activity level<select name="activityLevel"><option>${u.activityLevel||"Light"}</option><option>Sedentary</option><option>Light</option><option>Moderate</option><option>Active</option></select></label></div><div class="field"><label>Dietary preference<select name="dietaryPreference"><option>${u.dietaryPreference||"Vegetarian"}</option><option>Vegetarian</option><option>Eggitarian</option><option>Non-vegetarian</option></select></label></div><div class="field"><label>Daily budget<select name="budget"><option>${u.budget||"₹100/day"}</option><option>₹50/day</option><option>₹75/day</option><option>₹100/day</option><option>₹150/day</option><option>₹200+/day</option></select></label></div><div class="field full"><button class="btn btn-primary" type="submit">Save profile</button></div></form></section><section class="card"><p class="eyebrow">WELLNESS SNAPSHOT</p><div class="ring-layout" style="margin:22px 0"><div class="progress-ring" style="--value:${b?Math.min(100,Math.max(8,(b-15)/20*100)):0}"><strong>${b||"—"}</strong></div><div><h3>${bi.category}</h3><p class="muted" style="margin-top:7px;line-height:1.5">BMI is a screening measure, not a medical diagnosis.</p></div></div>${u.age&&u.age<18?`<div class="notice">For people under 18, adult BMI categories are not medically appropriate. Please use age-appropriate guidance from a healthcare professional.</div>`:`<p class="muted" style="line-height:1.6">${b?bi.category==="Healthy range"?"Your BMI sits within the standard adult healthy range. Keep focusing on strength, sleep and balanced meals.":"Use this screening result as one context point alongside energy, strength, sleep and how you feel.":"Add height and weight to calculate BMI."}</p>`}<div class="section-title"><h3>Achievements</h3></div><div class="grid grid-2">${badgeMarkup(s).slice(0,4).join("")}</div></section></div>`},
admin(){return`<div class="page-heading"><div><p class="eyebrow">ADMIN PORTAL · LOCAL DEMO</p><h2>Manage FitCampus content.</h2><p class="muted">Create, edit or remove custom exercises. Built-in exercises remain protected.</p></div><div class="timer-controls"><button class="btn btn-primary" data-admin-add>Add exercise</button><button class="btn btn-secondary" data-admin-plan>Custom plan</button><button class="btn btn-secondary" data-admin-event>Competitive event</button><button class="btn btn-secondary" data-admin-badge>Add badge</button></div></div><div class="grid grid-4"><div class="card metric-card"><span class="kicker">Registered users</span><p class="metric">${Store.users().length}</p></div><div class="card metric-card"><span class="kicker">Total activities</span><p class="metric">${Store.activities().length}</p></div><div class="card metric-card"><span class="kicker">Total points</span><p class="metric">${Store.users().reduce((n,u)=>n+(u.points||0),0)}</p></div><div class="card metric-card"><span class="kicker">Exercise library</span><p class="metric">${exercises.length}</p></div></div><div class="section-title"><h3>Exercise content</h3></div><section class="card table-wrap"><table class="table"><thead><tr><th>Exercise</th><th>Category</th><th>Difficulty</th><th>Duration</th><th>Status</th></tr></thead><tbody>${exercises.map(e=>`<tr><td><b>${escapeHtml(e.name)}</b></td><td>${escapeHtml(e.category)}</td><td>${escapeHtml(e.difficulty)}</td><td>${e.duration} min</td><td><span class="tag">${customExercises.some(c=>c.id===e.id)?"Created by admin":"Built-in"}</span>${customExercises.some(c=>c.id===e.id)?` <button class="text-btn" data-admin-edit="${e.id}">Edit</button> <button class="text-btn danger-btn" data-admin-delete="${e.id}">Delete</button>`:""}</td></tr>`).join("")}</tbody></table></section>`}
};
function planMarkup(u){const goal=u.fitnessGoal||"General fitness",b=bmi(u),p=bmiPlan(b,u.age),first=p.items[2];return`<section class="card" style="margin-bottom:18px"><p class="eyebrow">BMI-PERSONALISED PLAN</p><h3>${p.title}</h3><p class="muted" style="line-height:1.6;margin-top:8px">${p.summary}</p><p class="muted" style="font-size:.75rem;margin-top:10px">${p.note}</p></section><div class="grid grid-3"><div class="card"><p class="eyebrow">MORNING</p><h3>${p.items[0]}</h3><p class="muted" style="margin:8px 0 18px">Gentle start · sustainable pace</p><button class="btn btn-secondary" data-exercise="morning-mobility">Start</button></div><div class="card"><p class="eyebrow">STUDY BREAK</p><h3>${p.items[1]}</h3><p class="muted" style="margin:8px 0 18px">Reset posture and focus</p><button class="btn btn-secondary" data-route="desk">Start</button></div><div class="card"><p class="eyebrow">EVENING · ${escapeHtml(goal.toUpperCase())}</p><h3>${first}</h3><p class="muted" style="margin:8px 0 18px">Build consistency without extremes</p><button class="btn btn-secondary" data-exercise="strength-squat">Start</button></div></div>`}
function badgeMarkup(s){const a=s.acts,u=s.u;const checks={first:a.length>0,desk10:a.filter(x=>x.category==="Desk").length>=10,yoga5:a.filter(x=>x.category==="Yoga").length>=5,streak7:s.longest>=7,sessions30:a.length>=30,points500:(u.points||0)>=500,points1000:(u.points||0)>=1000,nutrition:!!Store.get(KEYS.plans,[]).some(x=>x.userId===u.id),water7:Object.keys(Store.water()).filter(k=>k.startsWith(`${u.id}-`)).length>=7};return badges.map(b=>`<div class="badge-card ${checks[b[0]]?"unlocked":""}"><div class="badge-icon">${b[1]}</div><strong>${b[2]}</strong><small>${checks[b[0]]?"Unlocked":b[3]}</small></div>`)}
function startTimer(ex,mode="exercise"){closeModal();const seconds=ex.duration*60;state.timer={remaining:seconds,total:seconds,exercise:ex,mode,sessionKey:uid(),running:true};openModal(ex.name,`<p class="modal-copy">${escapeHtml(ex.instructions)}</p><div class="timer-card"><div class="timer-display" id="live-timer">${formatTime(seconds)}</div><div class="timer-controls"><button class="btn btn-primary" data-timer-toggle>Pause</button><button class="btn btn-secondary" data-timer-reset>Restart</button><button class="btn btn-ghost" data-timer-finish>Finish</button></div><div class="notice">Move at a comfortable pace. This is a guided timer, not a medical test.</div></div>`);state.timer.interval=setInterval(()=>{if(!state.timer?.running)return;state.timer.remaining--;const live=document.getElementById("live-timer");if(live)live.textContent=formatTime(state.timer.remaining);if(state.timer.remaining<=0){clearInterval(state.timer.interval);state.timer.running=false;awardActivity(ex);closeModal();toast("Session complete — nice work!")}},1000)}
function formatTime(s){return`${String(Math.floor(Math.max(0,s)/60)).padStart(2,"0")}:${String(Math.max(0,s)%60).padStart(2,"0")}`}
function adminLoginModal(){openModal("Admin portal",`<p class="modal-copy">Admin access is required to publish plans, exercises, events and badges.</p><form id="admin-login-form" class="form-stack"><label>Admin password<input name="password" type="password" required autocomplete="current-password" placeholder="Enter admin password"></label><p id="admin-login-error" class="form-error" role="alert"></p><button class="btn btn-primary" type="submit">Enter admin portal</button></form>`)}
function adminExerciseModal(existing=null){const e=existing||{};openModal(existing?"Edit exercise":"Add exercise",`<form id="admin-exercise-form" class="form-stack"><input type="hidden" name="id" value="${escapeHtml(e.id||"")}"><label>Exercise name<input name="name" required value="${escapeHtml(e.name||"")}" placeholder="Campus mobility flow"></label><div class="form-grid"><label class="field">Category<select name="category"><option ${e.category==="Strength"?"selected":""}>Strength</option><option ${e.category==="Cardio"?"selected":""}>Cardio</option><option ${e.category==="Core"?"selected":""}>Core</option><option ${e.category==="Flexibility"?"selected":""}>Flexibility</option><option ${e.category==="Desk"?"selected":""}>Desk</option><option ${e.category==="Yoga"?"selected":""}>Yoga</option></select></label><label class="field">Difficulty<select name="difficulty"><option ${e.difficulty==="Beginner"?"selected":""}>Beginner</option><option ${e.difficulty==="Intermediate"?"selected":""}>Intermediate</option><option ${e.difficulty==="Advanced"?"selected":""}>Advanced</option></select></label></div><div class="form-grid"><label class="field">Duration (minutes)<input name="duration" type="number" min="1" max="120" value="${e.duration||10}" required></label><label class="field">Icon<input name="icon" value="${escapeHtml(e.icon||"✦")}" maxlength="2"></label></div><label>Description<textarea name="description" rows="2" required>${escapeHtml(e.description||"")}</textarea></label><label>Benefits<textarea name="benefits" rows="2" required placeholder="Improves posture, mobility and focus">${escapeHtml(e.benefits||"")}</textarea></label><label>Instructions<textarea name="instructions" rows="3" required>${escapeHtml(e.instructions||"")}</textarea></label><label>Safety tips<textarea name="safetyTips" rows="2" required>${escapeHtml(e.safetyTips||"")}</textarea></label><label>Tutorial video or link<input name="tutorialUrl" type="url" value="${escapeHtml(e.tutorialUrl||"")}" placeholder="https://..."></label><button class="btn btn-primary" type="submit">${existing?"Save changes":"Publish exercise"}</button></form>`);const form=document.getElementById("admin-exercise-form");if(form)form.addEventListener("submit",event=>{event.preventDefault();event.stopImmediatePropagation();saveAdminExercise(form)})}
function adminPlanModal(){openModal("Create custom plan",`<form id="admin-plan-form" class="form-stack"><label>Plan name<input name="name" required placeholder="Exam week reset"></label><label>Audience or goal<input name="goal" required placeholder="Stress reduction"></label><label>Plan steps<textarea name="steps" rows="5" required placeholder="5 min breathing&#10;10 min mobility&#10;20 min walk"></textarea></label><button class="btn btn-primary" type="submit">Publish plan</button></form>`)}
function adminEventModal(){openModal("Create competitive event",`<form id="admin-event-form" class="form-stack"><label>Event name<input name="name" required placeholder="Campus movement week"></label><label>Description<textarea name="description" rows="2" required></textarea></label><div class="form-grid"><label class="field">Start date<input name="startDate" type="date" required></label><label class="field">End date<input name="endDate" type="date" required></label><label class="field">Target<input name="target" type="number" min="1" required placeholder="5"></label><label class="field">Points<input name="points" type="number" min="1" required placeholder="50"></label></div><button class="btn btn-primary" type="submit">Publish event</button></form>`)}
function adminBadgeModal(){openModal("Add badge",`<form id="admin-badge-form" class="form-stack"><label>Badge name<input name="name" required placeholder="Morning mover"></label><label>Icon<input name="icon" value="🏅" maxlength="2"></label><label>Unlock rule<input name="rule" required placeholder="Complete 3 morning workouts"></label><button class="btn btn-primary" type="submit">Publish badge</button></form>`)}
function saveAdminExercise(form){const data=Object.fromEntries(new FormData(form)),created={...data,id:data.id||`custom-${uid()}`,duration:Number(data.duration),sets:3,reps:"8-12",muscles:"Full body",tutorialUrl:data.tutorialUrl||""};const index=customExercises.findIndex(x=>x.id===created.id);if(index>=0){customExercises[index]=created;const exerciseIndex=exercises.findIndex(x=>x.id===created.id);if(exerciseIndex>=0)exercises[exerciseIndex]=created;toast("Exercise updated")}else{customExercises.push(created);exercises.push(created);toast("Exercise published to the library")}Store.set("fc_custom_exercises",customExercises);closeModal();render()}
function bindPage(){document.querySelectorAll("[data-route]").forEach(b=>b.onclick=()=>{if(b.dataset.route==="admin"&&!adminUnlocked){adminLoginModal();return}state.route=b.dataset.route;document.getElementById("sidebar").classList.remove("open");render();window.scrollTo(0,0)});document.querySelectorAll("[data-exercise]").forEach(b=>b.onclick=()=>exerciseModal(exercises.find(e=>e.id===b.dataset.exercise)));document.querySelectorAll("[data-yoga-start]").forEach(b=>b.onclick=()=>{const s=yogaSessions.find(x=>x.id===b.dataset.yogaStart);startTimer({...exercises.find(e=>e.name==="Child's pose"),id:s.id,name:s.name,duration:s.duration,category:"Yoga"})});const search=document.getElementById("exercise-search");if(search)search.oninput=e=>{state.search=e.target.value.toLowerCase();render()};const cat=document.getElementById("category-filter");if(cat)cat.onchange=e=>{state.exerciseFilter=e.target.value;render()};document.querySelectorAll("[data-favorite]").forEach(b=>b.onclick=()=>{Store.toggleFavorite(b.dataset.favorite);toast(Store.isFavorite(b.dataset.favorite)?"Saved to favorites":"Removed from favorites");exerciseModal(exercises.find(e=>e.id===b.dataset.favorite))});document.querySelectorAll("[data-start-ex]").forEach(b=>b.onclick=()=>startTimer(exercises.find(e=>e.id===b.dataset.startEx)));document.querySelectorAll("[data-desk-start]").forEach(b=>b.onclick=()=>startTimer({...exercises.find(e=>e.id==="desk-march"),name:"5-minute study break",duration:5,category:"Desk"}));const pf=document.getElementById("profile-form");if(pf)pf.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(pf));const u=Store.user();const updated={...u,...data,age:Number(data.age)||null,height:Number(data.height)||null,weight:Number(data.weight)||null,bmi:bmi({...u,...data})};Store.saveUser(updated);toast("Profile updated");render()};document.querySelectorAll("[data-water]").forEach(b=>b.onclick=()=>{const u=Store.user(),w=Store.water(),key=`${u.id}-${today()}`;w[key]=Math.max(0,Math.min(20,(w[key]||0)+Number(b.dataset.water)));Store.set(KEYS.water,w);render()});document.querySelectorAll("[data-save-plan]").forEach(b=>b.onclick=()=>{const p=Store.get(KEYS.plans,[]);p.push({id:uid(),userId:Store.user().id,date:today()});Store.set(KEYS.plans,p);toast("Weekly plan saved");render()});document.querySelectorAll("[data-generate-plan]").forEach(b=>b.onclick=()=>toast("Plan refreshed from your preferences"));document.querySelectorAll("[data-open-bmi]").forEach(b=>b.onclick=bmiCalculatorModal);document.querySelectorAll("[data-calorie-estimate]").forEach(b=>b.onclick=calorieModal);document.querySelectorAll("[data-log-activity]").forEach(b=>b.onclick=()=>{const ex=exercises[0];startTimer({...ex,duration:1,name:"Logged movement"})});document.querySelectorAll("[data-admin-add]").forEach(b=>b.onclick=adminExerciseModal);document.querySelectorAll("[data-close-modal]").forEach(b=>b.onclick=e=>{if(e.target===b)closeModal()});const tt=document.querySelector("[data-timer-toggle]");if(tt)tt.onclick=()=>{state.timer.running=!state.timer.running;tt.textContent=state.timer.running?"Pause":"Resume"};const tr=document.querySelector("[data-timer-reset]");if(tr)tr.onclick=()=>{state.timer.remaining=state.timer.total;document.getElementById("live-timer").textContent=formatTime(state.timer.remaining)};const tf=document.querySelector("[data-timer-finish]");if(tf)tf.onclick=()=>{clearInterval(state.timer.interval);const ex=state.timer.exercise;const mins=Math.max(1,Math.ceil((state.timer.total-state.timer.remaining)/60));awardActivity(ex,mins,ex.category);closeModal()}}
document.addEventListener("click",e=>{const tab=e.target.closest("[data-auth-tab]");if(tab){document.querySelectorAll(".auth-tab").forEach(x=>x.classList.toggle("active",x===tab));document.getElementById("login-form-wrap").classList.toggle("hidden",tab.dataset.authTab!=="login");document.getElementById("signup-form-wrap").classList.toggle("hidden",tab.dataset.authTab!=="signup")}});
document.addEventListener("click",e=>{if(e.target.closest("[data-admin-add]"))adminExerciseModal();if(e.target.closest("[data-admin-plan]"))adminPlanModal();if(e.target.closest("[data-admin-event]"))adminEventModal();if(e.target.closest("[data-admin-badge]"))adminBadgeModal()});
document.addEventListener("click",e=>{const edit=e.target.closest("[data-admin-edit]");if(edit){const ex=customExercises.find(x=>x.id===edit.dataset.adminEdit);if(ex)adminExerciseModal(ex)}const remove=e.target.closest("[data-admin-delete]");if(remove&&confirm("Delete this custom exercise?")){const index=customExercises.findIndex(x=>x.id===remove.dataset.adminDelete);if(index>=0){customExercises.splice(index,1);const exerciseIndex=exercises.findIndex(x=>x.id===remove.dataset.adminDelete);if(exerciseIndex>=0)exercises.splice(exerciseIndex,1);Store.set("fc_custom_exercises",customExercises);toast("Exercise deleted");render()}}});
document.getElementById("signup-form").onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),email=f.get("email").toLowerCase(),users=Store.users();if(users.some(u=>u.email===email)){document.getElementById("signup-error").textContent="An account with this email already exists.";return}const u={id:uid(),name:f.get("name"),email,password:f.get("password"),department:f.get("department"),points:0,streak:0,longestStreak:0,createdAt:new Date().toISOString(),weeklyGoal:60};users.push(u);Store.set(KEYS.users,users);localStorage.setItem(KEYS.session,u.id);state.route="dashboard";render();toast("Welcome to FitCampus!")};
const enterUser=u=>{localStorage.setItem(KEYS.session,u.id);state.route="dashboard";render();toast(`Welcome back, ${u.name.split(" ")[0]}!`)};const demoUser=()=>{let u=Store.users().find(x=>x.email==="demo@fitcampus.app");if(!u){u={id:"demo-user",name:"Demo Student",email:"demo@fitcampus.app",password:"demo",department:"FitCampus Demo",points:120,streak:3,longestStreak:3,createdAt:new Date().toISOString(),weeklyGoal:60};Store.saveUser(u)}return u};document.getElementById("demo-login-btn").onclick=()=>enterUser(demoUser());document.getElementById("login-form").onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),email=String(f.get("email")||"").trim().toLowerCase(),password=String(f.get("password")||""),u=Store.users().find(x=>String(x.email||"").trim().toLowerCase()===email&&String(x.password||"")===password);if(!u){document.getElementById("login-error").textContent="Email or password is incorrect.";return}document.getElementById("login-error").textContent="";enterUser(u)};
const logout=()=>{localStorage.removeItem(KEYS.session);state.route="home";document.getElementById("sidebar").classList.remove("open");render();toast("You have been logged out.")};document.getElementById("logout-btn").onclick=logout;document.getElementById("top-logout-btn").onclick=logout;const sidebar=document.getElementById("sidebar"),mobileMenu=document.getElementById("mobile-menu"),sidebarClose=document.getElementById("sidebar-close");mobileMenu.onclick=()=>sidebar.classList.toggle("open");sidebarClose.onclick=()=>sidebar.classList.remove("open");document.addEventListener("click",e=>{if(window.innerWidth<=760&&sidebar.classList.contains("open")&&!sidebar.contains(e.target)&&e.target!==mobileMenu)sidebar.classList.remove("open")});document.getElementById("reminder-btn").onclick=()=>openModal("Study break reminder",`<p class="modal-copy">Choose a rhythm that protects your focus and your body. FitCampus never sends notifications without permission.</p><div class="grid grid-3"><button class="btn btn-secondary" data-reminder="25">25 / 5</button><button class="btn btn-secondary" data-reminder="50">50 / 5</button><button class="btn btn-ghost" data-close-modal>Not now</button></div>`);
document.getElementById("modal-root").addEventListener("click",e=>{const route=e.target.closest("[data-route-modal]");if(route){closeModal();state.route=route.dataset.routeModal;render();return}const close=e.target.closest("[data-close-modal]");if(close){if(close.classList.contains("modal-backdrop")&&e.target!==close)return;closeModal();return}const start=e.target.closest("[data-start-ex]");if(start){const ex=exercises.find(x=>x.id===start.dataset.startEx);if(ex)startTimer(ex);return}const fav=e.target.closest("[data-favorite]");if(fav){Store.toggleFavorite(fav.dataset.favorite);toast(Store.isFavorite(fav.dataset.favorite)?"Saved to favorites":"Removed from favorites");return}const toggle=e.target.closest("[data-timer-toggle]");if(toggle&&state.timer){state.timer.running=!state.timer.running;toggle.textContent=state.timer.running?"Pause":"Resume";return}const reset=e.target.closest("[data-timer-reset]");if(reset&&state.timer){state.timer.remaining=state.timer.total;const live=document.getElementById("live-timer");if(live)live.textContent=formatTime(state.timer.remaining);return}const finish=e.target.closest("[data-timer-finish]");if(finish&&state.timer){clearInterval(state.timer.interval);const ex=state.timer.exercise;const mins=Math.max(1,Math.ceil((state.timer.total-state.timer.remaining)/60));awardActivity(ex,mins,ex.category);closeModal();return}const play=e.target.closest("[data-motion-play]");if(play){const stage=document.querySelector("[data-motion-stage]");if(stage){stage.classList.toggle("playing");play.textContent=stage.classList.contains("playing")?"Pause":"Play";const caption=document.querySelector("[data-motion-caption]");if(caption)caption.textContent=stage.classList.contains("playing")?"Animating movement stages":"3D-style movement preview · ready"}return}const slow=e.target.closest("[data-motion-slow]");if(slow){document.querySelector("[data-motion-stage]")?.classList.toggle("slow");return}const rotate=e.target.closest("[data-motion-rotate]");if(rotate){const stage=document.querySelector("[data-motion-stage]");if(stage)stage.style.transform=`rotateY(${Math.round(Math.random()*160-80)}deg) rotateX(${Math.round(Math.random()*20-10)}deg)`;return}const r=e.target.closest("[data-reminder]");if(r){closeModal();toast(`Reminder set: move after ${r.dataset.reminder} minutes.`)}});
document.getElementById("modal-root").addEventListener("submit",e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(e.target.id==="admin-login-form"){if(data.password!==ADMIN_PASSWORD){e.target.querySelector("#admin-login-error").textContent="Incorrect admin password.";return}adminUnlocked=true;sessionStorage.setItem("fc_admin_unlocked","1");closeModal();state.route="admin";render();return}if(e.target.id==="admin-exercise-form"){const created={...data,id:data.id||`custom-${uid()}`,duration:Number(data.duration),sets:3,reps:"8-12",muscles:"Full body",tutorialUrl:data.tutorialUrl||""};const index=customExercises.findIndex(x=>x.id===created.id);if(index>=0){customExercises[index]=created;const exerciseIndex=exercises.findIndex(x=>x.id===created.id);if(exerciseIndex>=0)exercises[exerciseIndex]=created;toast("Exercise updated")}else{customExercises.push(created);exercises.push(created);toast("Exercise published to the library")}Store.set("fc_custom_exercises",customExercises);closeModal();render();return}if(e.target.id==="admin-plan-form"){const plans=Store.get(KEYS.plans,[]);plans.push({...data,id:uid(),createdBy:"admin",createdAt:today()});Store.set(KEYS.plans,plans);closeModal();toast("Custom plan published");return}if(e.target.id==="admin-event-form"){const events=Store.get(KEYS.events,[]);events.push({...data,id:uid(),points:Number(data.points),target:Number(data.target)});Store.set(KEYS.events,events);closeModal();toast("Competitive event published");return}if(e.target.id==="admin-badge-form"){customBadges.push({...data,id:uid()});Store.set(KEYS.badges,customBadges);closeModal();toast("Badge published");return}});
render();
